     ];
-    const ABBR: [&str; 12] = [
+    const EN_ABBR: [&str; 12] = [
         "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
     ];
-    match month.checked_sub(1).and_then(|i| usize::try_from(i).ok()) {
