+        "déc.",
+    ];
+    let Some(i) = month
+        .checked_sub(1)
+        .and_then(|i| usize::try_from(i).ok())
+        .filter(|i| *i < 12)
+    else {
+        return "";
+    };
+    let sub = primary_subtag(lang);
+    let (full, abbr): (&[&str; 12], &[&str; 12]) = if sub.eq_ignore_ascii_case("de") {
+        (&DE_FULL, &DE_ABBR)
+    } else if sub.eq_ignore_ascii_case("fr") {
+        (&FR_FULL, &FR_ABBR)
+    } else {
+        (&EN_FULL, &EN_ABBR)
+    };
+    if abbrev { abbr[i] } else { full[i] }
 }

