+    fn date_localizes_month_names() {
+        // `%B`/`%b` follow the language; numeric fields do not. Unknown tags → English.
+        assert_eq!(date("2026-06-09", "%d. %B %Y", "de"), "09. Juni 2026");
+        assert_eq!(date("2026-03-02", "%b", "de"), "Mär");
